import torch  
import torch.nn as nn

class SimpleNet(nn.Module):  
    def __init__(self):  
        super().__init__()  
        self.fc = nn.Linear(4, 2)

    def forward(self, x):  
        return self.fc(x)

net = SimpleNet()  
features = {}

# Define forward hook to store activation  
def get_activation(name):  
    def hook(module, input, output):  
        features[name] = output.detach()  
    return hook

# Attach hook to fc layer  
handle = net.fc.register_forward_hook(get_activation('fc_layer'))

x = torch.randn(1, 4)  
_ = net(x)

print(f"Captured activation shape: {features['fc_layer'].shape}")  
handle.remove()

